\set F '00000000-0000-0000-0000-0000000000f1'
\set L '00000000-0000-0000-0000-00000000a001'
\set M '00000000-0000-0000-0000-00000000b001'
\set A '00000000-0000-0000-0000-00000000c001'
select '01 doublon de fonction refusé par la base (même compte, fonction, organisation)', pg_temp.essai(:'F', $q$insert into bellaia_roles(user_id, role, organisation_id) values ('00000000-0000-0000-0000-00000000a001','hote','00000000-0000-0000-0000-0000000000c1')$q$) = 'refusé';
select '02 même fonction dans un autre pôle (équipe interne) acceptée', pg_temp.essai(:'F', $q$insert into bellaia_roles(user_id, role) values ('00000000-0000-0000-0000-00000000a001','hote')$q$) = 'accepté';
select '03 … et une seule fois (doublon interne refusé)', pg_temp.essai(:'F', $q$insert into bellaia_roles(user_id, role) values ('00000000-0000-0000-0000-00000000a001','hote')$q$) = 'refusé';
select '04 journal : l''auteur du changement est enregistré', (select user_id from bellaia_journal where action = 'bellaia_roles.insert' order by id desc limit 1) = :'F';
select '05 auto-attribution refusée : une partenaire ne s''ajoute pas de fonction', pg_temp.essai(:'L', $q$insert into bellaia_roles(user_id, role) values (auth.uid(), 'qualite')$q$) = 'refusé';
select '06 élévation refusée : une partenaire ne modifie pas ses fonctions (0 ligne)', pg_temp.compte(:'L', $q$with u as (update bellaia_roles set statut = 'actif', organisation_id = null returning 1) select count(*) from u$q$) = 0;
select '07 répertoire complet : fondatrice (comptes + e-mails, fondatrice exclue)', pg_temp.compte(:'F', $q$select jsonb_array_length(repertoire_contacts())$q$) = 3 and pg_temp.compte(:'F', $q$select count(*) from jsonb_array_elements(repertoire_contacts()) x where x->>'email' like '%@exemple.invalid'$q$) = 3;
select '08 catégories et pôles déduits (Lina : hôtes, assistants, collaborateurs, partenaires ; Vil''Dor et FOOD)', pg_temp.compte(:'F', $q$select count(*) from jsonb_array_elements(repertoire_contacts()) x where x->>'id' = '00000000-0000-0000-0000-00000000a001' and x->'categories' ?& array['hotes','assistants','collaborateurs','partenaires'] and x->'poles' ?& array['VILDOR','FOOD']$q$) = 1;
select '09 répertoire refusé aux autres comptes (partenaire, assistante, cliente) : liste vide', pg_temp.compte(:'L', $q$select jsonb_array_length(repertoire_contacts())$q$) = 0 and pg_temp.compte(:'A', $q$select jsonb_array_length(repertoire_contacts())$q$) = 0 and pg_temp.compte(:'M', $q$select jsonb_array_length(repertoire_contacts())$q$) = 0;
select '10 visiteur anonyme : fonction inaccessible', pg_temp.compte_anon($q$select jsonb_array_length(repertoire_contacts())$q$) = -1;
select '11 contact externe (fournisseur) créé sans compte', pg_temp.essai(:'F', $q$insert into bellaia_repertoire(prenom, nom, entreprise, email, categories, poles) values ('Hélène','ÉLÉONORE','Fournil du Sud','contact@fournil.invalid','{fournisseurs}','{FOOD}')$q$) = 'accepté';
select '11b … présent dans le répertoire comme contact externe, aucun compte créé', pg_temp.compte(:'F', $q$select count(*) from jsonb_array_elements(repertoire_contacts()) x where x->>'compte' = 'false' and x->>'entreprise' = 'Fournil du Sud'$q$) = 1 and (select count(*) from auth.users) = 4;
select '12 catégorie inconnue refusée ; nouvelle catégorie créée puis utilisable', pg_temp.essai(:'F', $q$insert into bellaia_repertoire(nom, categories) values ('X','{inconnue}')$q$) = 'refusé'
  and pg_temp.essai(:'F', $q$insert into bellaia_repertoire_categories(id, libelle) values ('traiteurs','Traiteurs'); insert into bellaia_repertoire(nom, entreprise, categories) values ('Y','Traiteur Y','{traiteurs}')$q$) = 'accepté';
select '13 renommer une catégorie', pg_temp.essai(:'F', $q$update bellaia_repertoire_categories set libelle = 'Prospects chauds' where id = 'prospects'$q$) = 'accepté';
select '14 fiche sans identité (ni nom, prénom, e-mail, entreprise) refusée ; e-mail invalide refusé', pg_temp.essai(:'F', $q$insert into bellaia_repertoire(telephone) values ('0694000000')$q$) = 'refusé' and pg_temp.essai(:'F', $q$insert into bellaia_repertoire(nom, email) values ('Z','pas-un-email')$q$) = 'refusé';
select '15 fiche complémentaire d''un compte (pseudo, entreprise) visible dans la recherche', pg_temp.essai(:'F', $q$insert into bellaia_repertoire(user_id, pseudo, entreprise, categories) values ('00000000-0000-0000-0000-00000000a001','Lina V.','Vil''Dor Pâtisse','{responsables_poles}')$q$) = 'accepté'
  and pg_temp.compte(:'F', $q$select count(*) from jsonb_array_elements(repertoire_contacts()) x where x->>'pseudo' = 'Lina V.' and x->'categories' ? 'responsables_poles'$q$) = 1;
select '16 une seule fiche par compte', pg_temp.essai(:'F', $q$insert into bellaia_repertoire(user_id, nom) values ('00000000-0000-0000-0000-00000000a001','doublon')$q$) = 'refusé';
select '17 répertoire illisible pour les autres comptes (lecture directe)', pg_temp.compte(:'L', $q$select count(*) from bellaia_repertoire$q$) = 0 and pg_temp.compte(:'A', $q$select count(*) from bellaia_repertoire$q$) = 0 and pg_temp.compte_anon($q$select count(*) from bellaia_repertoire$q$) <= 0;
select '18 modifications du répertoire journalisées (sans les notes internes)', (select count(*) from bellaia_journal where action like 'bellaia_repertoire.%') >= 3 and not exists (select 1 from bellaia_journal where details::text like '%notes_internes%');
select '19 archivage : la fiche passe en « Contacts archivés » sans être supprimée', pg_temp.essai(:'F', $q$update bellaia_repertoire set archive = true where entreprise = 'Fournil du Sud'$q$) = 'accepté' and pg_temp.compte(:'F', $q$select count(*) from jsonb_array_elements(repertoire_contacts()) x where x->'categories' ? 'archives'$q$) = 1;
